package com.movieworth.api.movie;import com.movieworth.api.boxoffice.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.util.*;
@RestController @RequestMapping("/api/movies") public class MovieController{private final MovieRepository movies;private final CollectionRepository collections;private final TmdbService tmdb;public MovieController(MovieRepository m,CollectionRepository c,TmdbService t){movies=m;collections=c;tmdb=t;}
@GetMapping public List<Movie> all(){return movies.findTop30ByOrderByPopularityDesc();}@GetMapping("/{id}")public Movie one(@PathVariable Long id){return movies.findById(id).orElseThrow(()->new NoSuchElementException("Movie not found"));}@GetMapping("/trending")public List<Movie> trending(){return all();}@GetMapping("/search")public List<Movie> search(@RequestParam String q){return movies.search(q);}@GetMapping("/{id}/collections")public List<CollectionSnapshot> history(@PathVariable Long id){return collections.findByMovieIdOrderByCollectionDateDesc(id);}
@PostMapping("/sync/tmdb")public Map<String,Object> sync(){List<Movie> list=tmdb.discover();return Map.of("updated",list.size(),"provider","TMDB");}}
